   assign dataout[17] 	  = datain[17];
   assign dataout[16] 	  = (rxre_state==RXRE_DUMMY) | (datain[17] & datain[16]);  assign dataout[15:0] = datain[15:0];

   always @(posedge clk)
     if(reset | clear)
       rxre_state <= RXRE_DUMMY;
