   // Double-width register to store the concatenation of 'd' and 'in'
   reg [63:0] d_reg;

   // Always-FF block to update the register on the rising edge of the clock
   always @(posedge clk) begin
      d_reg <= {d_reg[31:0], in[0] ? in : 32'b0};
