  input B,
  input Cin,
  output S,
  output Cout
);

  wire s1, s2, c1, c2;

  // First stage
  xor(s1, A, B);
  xor(S, s1, Cin);

  // Second stage
  and(c1, A, B);
  and(c2, s1, Cin);
  or(Cout, c1, c2);

endmodule

