	 input rst,
	 input [1:0] piso, input [1:0] accion, input puertas, output reg [3:0] BCD1,
	 output reg [3:0] BCD2,
	 output reg [3:0] BCD3,
	 output reg [3:0] BCD4
    );

initial begin
	BCD4 = 1;
	BCD3 = 9;
	BCD2 = 6;
	BCD1 = 0;
end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD4 = 4'b1110;
				#10 BCD4 = 4'b0001;
				BCD3 = 4'b0110;
				#10 BCD3 = 4'b1001;
			end
		else
			begin
				if (piso == 2'b00)
					BCD4 = 4'b0001;
				else if (piso == 2'b01)
					BCD4 = 4'b0010;
				else if (piso == 2'b10)
					BCD4 = 4'b0011;
				else
					BCD4 = 4'b0100;
