  assign BSEL = (OP == 3'b001) ? 1'b1 : 1'b0;



  always @(*) begin

	case (OP)

		ADD: begin 

			  OSEL = 2'b0;

			  SHIFT_LA = 1'b0;

			  SHIFT_LR = 1'b0;

			  LOGICAL_OP = 1'b0;

		end

