        green_light <= 1;
        yellow_light <= 0;
        red_light <= 0;
        if (pedestrian_crossing_button) begin
          next_state <= S1;
        end else begin
          next_state <= S0;
        end
      end
      S1: begin
        green_light <= 0;
        yellow_light <= 1;
        red_light <= 0;
        next_state <= S2;
